import re

from django.db import migrations, models


def lines_to_promos(apps, schema_editor):
    """the old one-box flyer (a line per promo: ชื่อ | ราคา | รายละเอียด, "220.- (240.-)" = price + usual price,
    one end date for all) becomes one Promo row per line, same end date, showing from now"""
    ShopInfo = apps.get_model("menu", "ShopInfo")
    Promo = apps.get_model("menu", "Promo")
    for info in ShopInfo.objects.all():
        for line in (info.promo or "").splitlines():
            line = line.strip().lstrip("-•· ").strip()
            if not line:
                continue
            name, price, detail = ([x.strip() for x in line.split("|", 2)] + ["", ""])[:3]
            was = ""
            m = re.fullmatch(r"(.*?)\s*\((.+)\)", price)
            if m and m.group(1):
                price, was = m.group(1).strip(), m.group(2).strip()
            Promo.objects.create(name=name[:120] or "โปร", price=price[:30], was=was[:30], detail=detail[:160], ends=info.promo_until)


